69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
78	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
79	     */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    private final ClinicService clinicService;
83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    /**
126	     * Rejects an owner payload that is missing or blank in any of the required fields
127	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
128	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
129	     * value as present; this guard closes that gap so a blank in any required field is
130	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
131	     * the name of each offending field.
132	     */
133	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
134	        List<String> missing = new ArrayList<>();
135	        if (isBlank(ownerFieldsDto.getFirstName())) {
136	            missing.add("firstName");
137	        }
138	        if (isBlank(ownerFieldsDto.getLastName())) {
139	            missing.add("lastName");
140	        }
141	        if (isBlank(normalizedAddress)) {
142	            missing.add("address");
143	        }
144	        if (isBlank(ownerFieldsDto.getCity())) {
145	            missing.add("city");
146	        }
147	        if (isBlank(ownerFieldsDto.getTelephone())) {
148	            missing.add("telephone");
149	        }
150	        if (!missing.isEmpty()) {
151	            throw new MissingOwnerFieldsException(missing);
152	        }
153	    }
154	
155	    private static boolean isBlank(String value) {
156	        return value == null || value.isBlank();
157	    }
158	
159	    /**
160	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
161	     */
162	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
163	
164	    /**
165	     * Required national-number length per country calling code. When the normalized E.164 number
166	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
167	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
168	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
169	     */
170	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
171	        "+61", 9,
172	        "+1", 10);
173	
174	    /**
175	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
176	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
177	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
178	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
179	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
180	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
181	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
182	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
183	     * translates to a 400.
184	     */
185	    private static String normalizeTelephone(String telephone) {
186	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
187	        String e164;
188	        if (cleaned.startsWith("+")) {
189	            e164 = cleaned;
190	        } else {
191	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
192	            e164 = "+61" + national;
193	        }
194	        if (!E164_PATTERN.matcher(e164).matches()) {
195	            throw new InvalidTelephoneException(telephone);
196	        }
197	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
198	            String code = rule.getKey();
199	            if (e164.startsWith(code)) {
200	                int nationalLength = e164.length() - code.length();
201	                if (nationalLength != rule.getValue()) {
202	                    throw new InvalidTelephoneException(telephone);
203	                }
204	                break;
205	            }
206	        }
207	        return e164;
208	    }
209	
210	    /**
211	     * Matches a well-formed postcode: exactly four digits.
212	     */
213	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
214	
215	    /**
216	     * The canonical region for each city that has one. A city absent from this table has no known
217	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
218	     * to derive an owner's locality.
219	     */
220	    private static final Map<String, String> CITY_REGION = Map.of(
221	        "Sydney", "NSW",
222	        "Melbourne", "VIC",
223	        "Brisbane", "QLD");
224	
225	    /**
226	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
227	     * VIC 3000-3099, QLD 4000-4099.
228	     */
229	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
230	        "NSW", new int[] {2000, 2099},
231	        "VIC", new int[] {3000, 3099},
232	        "QLD", new int[] {4000, 4099});
233	
234	    /**
235	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
236	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
237	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
238	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
239	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
240	     * exception handler translates to a 400.
241	     */
242	    private static void validatePostcode(String city, String postcode) {
243	        if (postcode == null) {
244	            return;
245	        }
246	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
247	            throw new InvalidPostcodeException(postcode);
248	        }
249	        String region = CITY_REGION.get(city);
250	        if (region == null) {
251	            return;
252	        }
253	        int[] range = REGION_POSTCODES.get(region);
254	        int value = Integer.parseInt(postcode);
255	        if (value < range[0] || value > range[1]) {
256	            throw new InvalidPostcodeException(postcode);
257	        }
258	    }
259	
260	    /**
261	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
262	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
263	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
264	     */
265	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
266	
267	    /**
268	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
269	     * optional). When present it must be a syntactically valid address; a valid value is
270	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
271	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
272	     */
273	    private static String normalizeEmail(String email) {
274	        if (email == null) {
275	            return null;
276	        }
277	        if (!EMAIL_PATTERN.matcher(email).matches()) {
278	            throw new InvalidEmailException(email);
279	        }
280	        return email.toLowerCase(Locale.ROOT);
281	    }
282	
283	    /**
284	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
285	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
286	     * same identity only when this whole key matches: because the normalized telephone is part of
287	     * the key, two members of the same household (same {@code householdId}) with different
288	     * telephones have different identity keys. A {@code null} email contributes an empty middle
289	     * segment. This is the value returned to callers as {@code identityKey}.
290	     */
291	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
292	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
293	    }
294	
295	    /**
296	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
297	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
298	     * telephone, email and household checks are now expressed through the components of the single
299	     * identity key:
300	     * <ul>
301	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
302	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
303	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
304	     *       candidate email, being optional, is not compared, and existing owners without an email
305	     *       are skipped);</li>
306	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
307	     *       a household via {@code sharesHousehold}, in which case the household component is not
308	     *       compared.</li>
309	     * </ul>
310	     */
311	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
312	                                         String normalizedEmail, String householdId) {
313	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
314	        for (Owner existing : this.clinicService.findAllOwners()) {
315	            String existingTelephone;
316	            try {
317	                existingTelephone = normalizeTelephone(existing.getTelephone());
318	            } catch (InvalidTelephoneException ex) {
319	                existingTelephone = null;
320	            }
321	            if (normalizedTelephone.equals(existingTelephone)) {
322	                throw new DuplicateTelephoneException(normalizedTelephone);
323	            }
324	            if (normalizedEmail != null) {
325	                String existingEmail = existing.getEmail();
326	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
327	                    throw new DuplicateEmailException(normalizedEmail);
328	                }
329	            }
330	            if (!sharesHousehold
331	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getPostcode()))) {
332	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
333	            }
334	        }
335	    }
336	
337	    /**
338	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
339	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
340	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
341	     * spacing do not defeat the duplicate-household check.
342	     */
343	    private static String collapse(String value) {
344	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
345	    }
346	
347	    /**
348	     * Normalizes an owner's address into a canonical form applied on every create: leading and
349	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
350	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
351	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
352	     * and returned, and is the form every address comparison (duplicate-household detection and the
353	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
354	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
355	     * so normalizing an already-normalized address is a no-op.
356	     */
357	    private static String normalizeAddress(String address) {
358	        if (address == null) {
359	            return "";
360	        }
361	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
362	        if (collapsed.isEmpty()) {
363	            return "";
364	        }
365	        String[] tokens = collapsed.split(" ");
366	        StringBuilder sb = new StringBuilder(collapsed.length());
367	        for (int i = 0; i < tokens.length; i++) {
368	            String token = tokens[i];
369	            switch (token) {
370	                case "ST" -> token = "STREET";
371	                case "RD" -> token = "ROAD";
372	                case "AVE" -> token = "AVENUE";
373	                default -> {
374	                }
375	            }
376	            if (i > 0) {
377	                sb.append(' ');
378	            }
379	            sb.append(token);
380	        }
381	        return sb.toString();
382	    }
383	
384	    /**
385	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
386	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
387	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
388	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
389	     * region derivation shared by the {@code customerCode} and the owner's locality.
390	     */
391	    private static String deriveRegion(String city, String postcode) {
392	        if (postcode != null) {
393	            try {
394	                int pc = Integer.parseInt(postcode.trim());
395	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
396	                    int[] bounds = range.getValue();
397	                    if (pc >= bounds[0] && pc <= bounds[1]) {
398	                        return range.getKey();
399	                    }
400	                }
401	            } catch (NumberFormatException ignored) {
402	                // not a numeric postcode; fall back to the city-to-region table
403	            }
404	        }
405	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
406	    }
407	
408	    /**
409	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
410	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
411	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
412	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
413	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
414	     */
415	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
416	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
417	    }
418	
419	    /**
420	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
421	     * bytes of {@code value}.
422	     */
423	    private static String sha256HexPrefix(String value, int hexChars) {
424	        try {
425	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
426	            StringBuilder sb = new StringBuilder(hexChars);
427	            for (byte b : digest) {
428	                if (sb.length() >= hexChars) {
429	                    break;
430	                }
431	                sb.append(String.format("%02X", b));
432	            }
433	            return sb.substring(0, hexChars);
434	        } catch (NoSuchAlgorithmException ex) {
435	            throw new IllegalStateException("SHA-256 not available", ex);
436	        }
437	    }
438	
439	    /**
440	     * Builds the {@code membershipNumber} for a newly created owner, formatted
441	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
442	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
443	     */
444	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
445	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
446	    }
447	
448	    /**
449	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
450	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
451	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
452	     * it is a pure function of that pair, every owner in the same household - whether created first
453	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
454	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
455	     * segment.
456	     */
457	    private static String householdIdFor(String lastName, String postcode) {
458	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
459	        try {
460	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
461	            StringBuilder sb = new StringBuilder(12);
462	            for (byte b : digest) {
463	                if (sb.length() >= 12) {
464	                    break;
465	                }
466	                sb.append(String.format("%02x", b));
467	            }
468	            return sb.substring(0, 12);
469	        } catch (NoSuchAlgorithmException ex) {
470	            throw new IllegalStateException("SHA-256 not available", ex);
471	        }
472	    }
473	
474	    /**
475	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
476	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
477	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
478	     */
479	    private int countNamesakes(String firstName, String lastName) {
480	        int count = 0;
481	        for (Owner existing : this.clinicService.findAllOwners()) {
482	            if (firstName.equalsIgnoreCase(existing.getFirstName())
483	                && lastName.equalsIgnoreCase(existing.getLastName())) {
484	                count++;
485	            }
486	        }
487	        return count;
488	    }
489	
490	    /**
491	     * Counts the members of the household the new owner will belong to, as it stands after this
492	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
493	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
494	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
495	     * stored on the owner as its {@code householdMemberCount}.
496	     */
497	    private int countHouseholdMembers(String householdId) {
498	        int count = 1;
499	        for (Owner existing : this.clinicService.findAllOwners()) {
500	            if (householdId.equals(existing.getHouseholdId())) {
501	                count++;
502	            }
503	        }
504	        return count;
505	    }
506	
507	    /**
508	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
509	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
510	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
511	     * new owner's postcode must be present for a soft match to be possible. When several existing
512	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
513	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
514	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
515	     *
516	     * <p>Because the household is now keyed on {@code (lastName, postcode)} - exactly the soft-match
517	     * key - a co-member reached here can only be one the caller declared via {@code sharesHousehold}
518	     * (otherwise the hard household-duplicate check would already have rejected it). A declared
519	     * household member is not a suspected duplicate, so no soft match is reported in that case.
520	     */
521	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
522	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
523	            return null;
524	        }
525	        String postcode = ownerFieldsDto.getPostcode();
526	        if (postcode == null) {
527	            return null;
528	        }
529	        String lastName = ownerFieldsDto.getLastName();
530	        Integer matchId = null;
531	        for (Owner existing : this.clinicService.findAllOwners()) {
532	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
533	                continue;
534	            }
535	            if (!postcode.equals(existing.getPostcode())) {
536	                continue;
537	            }
538	            String existingTelephone;
539	            try {
540	                existingTelephone = normalizeTelephone(existing.getTelephone());
541	            } catch (InvalidTelephoneException ex) {
542	                existingTelephone = null;
543	            }
544	            if (normalizedTelephone.equals(existingTelephone)) {
545	                continue;
546	            }
547	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
548	                matchId = existing.getId();
549	            }
550	        }
551	        return matchId;
552	    }
553	
554	    /**
555	     * The membership level ceiling assigned on create; level 4 is reserved for tenure and so is
556	     * never reached here.
557	     */
558	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
559	
560	    /**
561	     * Computes the numeric {@code membershipLevel} for a newly created owner. It starts at 1,
562	     * gains 1 when an email is present, gains 1 when the owner's {@code namesakeCount} is 0, and
563	     * is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure). Evaluated after
564	     * the owner's email and namesakeCount have been set.
565	     */
566	    private static int membershipLevelFor(Owner owner) {
567	        int level = 1;
568	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
569	            level++;
570	        }
571	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
572	            level++;
573	        }
574	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
575	    }
576	
577	    /**
578	     * The maximum number of owners any single city may contain. A create whose city already
579	     * holds this many owners is rejected.
580	     */
581	    private static final int CITY_CAPACITY = 50;
582	
583	    /**
584	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
585	     * compared case-insensitively - the same way the city is matched when building the
586	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
587	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
588	     * translates to a 409.
589	     */
590	    private void rejectCityAtCapacity(String city) {
591	        int count = 0;
592	        for (Owner existing : this.clinicService.findAllOwners()) {
593	            if (city.equalsIgnoreCase(existing.getCity())) {
594	                count++;
595	            }
596	        }
597	        if (count >= CITY_CAPACITY) {
598	            throw new CityAtCapacityException(city);
599	        }
600	    }
601	
602	    /**
603	     * The maximum number of owners that may be created on any single day (by
604	     * {@code registrationDate}). A create attempted once this many owners already carry the
605	     * current day's registration date is rejected.
606	     */
607	    private static final int DAILY_OWNER_LIMIT = 100;
608	
609	    /**
610	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
611	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
612	     * The count reflects the state prior to this create. When the limit is reached the create is
613	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
614	     * to a 429 Too Many Requests.
615	     */
616	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
617	        int count = 0;
618	        for (Owner existing : this.clinicService.findAllOwners()) {
619	            if (registrationDate.equals(existing.getRegistrationDate())) {
620	                count++;
621	            }
622	        }
623	        if (count >= DAILY_OWNER_LIMIT) {
624	            throw new DailyOwnerLimitExceededException();
625	        }
626	    }
627	
628	    /**
629	     * The number of owners that must already carry a given {@code registrationDate} before a
630	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
631	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
632	     */
633	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
634	
635	    /**
636	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
637	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
638	     * have already been created for that date, otherwise false. The count reflects the state prior
639	     * to this create, matching how the daily-limit rule accumulates.
640	     */
641	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
642	        int count = 0;
643	        for (Owner existing : this.clinicService.findAllOwners()) {
644	            if (registrationDate.equals(existing.getRegistrationDate())) {
645	                count++;
646	            }
647	        }
648	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
649	    }
650	
651	    /**
652	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
653	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
654	     * effective registration date - whether supplied in the request or defaulted to the server
655	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
656	     * on a business day.
657	     */
658	    /**
659	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
660	     * only ever explicitly supplied on the request; when present it must not be later than the
661	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
662	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
663	     * later from the server date) is accepted.
664	     */
665	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
666	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
667	            throw new FutureRegistrationDateException(registrationDate);
668	        }
669	    }
670	
671	    private static LocalDate toBusinessDay(LocalDate date) {
672	        return switch (date.getDayOfWeek()) {
673	            case SATURDAY -> date.plusDays(2);
674	            case SUNDAY -> date.plusDays(1);
675	            default -> date;
676	        };
677	    }
678	
679	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
680	    @Override
681	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
682	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
683	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
684	        rejectCityAtCapacity(ownerFieldsDto.getCity());
685	        HttpHeaders headers = new HttpHeaders();
686	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
687	        owner.setAddress(normalizedAddress);
688	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
689	        owner.setTelephone(normalizedTelephone);
690	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
691	        owner.setEmail(normalizedEmail);
692	        validatePostcode(owner.getCity(), owner.getPostcode());
693	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
694	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
695	        rejectFutureRegistrationDate(owner.getRegistrationDate());
696	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
697	        LocalDate registrationDate = toBusinessDay(effectiveDate);
698	        rejectDailyOwnerLimit(registrationDate);
699	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
700	        owner.setRegistrationDate(registrationDate);
701	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
702	        owner.setCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName()));
703	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
704	        owner.setHouseholdId(householdId);
705	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
706	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
707	        owner.setMembershipLevel(membershipLevelFor(owner));
708	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone);
709	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
710	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
711	        this.clinicService.saveOwner(owner);
712	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
713	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
714	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
715	        headers.setLocation(UriComponentsBuilder.newInstance()
716	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
717	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
718	    }
719	
720	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
721	    @Override
722	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
723	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
724	        if (currentOwner == null) {
725	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
726	        }
727	        currentOwner.setAddress(ownerFieldsDto.getAddress());
728	        currentOwner.setCity(ownerFieldsDto.getCity());
729	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
730	        currentOwner.setLastName(ownerFieldsDto.getLastName());
731	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
732	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
733	        this.clinicService.saveOwner(currentOwner);
734	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
735	    }
736	
737	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
738	    @Transactional
739	    @Override
740	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
741	        Owner owner = this.clinicService.findOwnerById(ownerId);
742	        if (owner == null) {
743	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
744	        }
745	        this.clinicService.deleteOwner(owner);
746	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
747	    }
748	
749	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
750	    @Override
751	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
752	        Owner owner = this.clinicService.findOwnerById(ownerId);
753	        if (owner == null) {
754	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
755	        }
756	        HttpHeaders headers = new HttpHeaders();
757	        Pet pet = petMapper.toPet(petFieldsDto);
758	        owner.setId(ownerId);
759	        pet.setOwner(owner);
760	        pet.getType().setName(null);
761	        this.clinicService.savePet(pet);
762	        PetDto petDto = petMapper.toPetDto(pet);
763	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
764	            .buildAndExpand(pet.getId()).toUri());
765	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
766	    }
767	
768	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
769	    @Override
770	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
771	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
772	        if (currentOwner != null) {
773	            Pet currentPet = this.clinicService.findPetById(petId);
774	            if (currentPet != null) {
775	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
776	                currentPet.setName(petFieldsDto.getName());
777	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
778	                this.clinicService.savePet(currentPet);
779	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
780	            }
781	        }
782	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
783	    }
784	
785	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
786	    @Override
787	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
788	        HttpHeaders headers = new HttpHeaders();
789	        Visit visit = visitMapper.toVisit(visitFieldsDto);
790	        Pet pet = new Pet();
791	        pet.setId(petId);
792	        visit.setPet(pet);
793	        this.clinicService.saveVisit(visit);
794	        VisitDto visitDto = visitMapper.toVisitDto(visit);
795	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
796	            .buildAndExpand(visit.getId()).toUri());
797	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
798	    }
799	
800	
801	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
802	    @Override
803	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
804	        Owner owner = this.clinicService.findOwnerById(ownerId);
805	        if (owner != null) {
806	            Pet pet = owner.getPet(petId);
807	            if (pet != null) {
808	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
809	            }
810	        }
811	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
812	    }
813	}
