package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when an owner's email is present but is not a syntactically valid address. The
 * exception handler translates it to a 400 Bad Request whose {@code errors} array names the
 * offending {@code email} field.
 */
public class InvalidEmailException extends RuntimeException {

    public InvalidEmailException(String email) {
        super("Email must be a syntactically valid address: " + email);
    }
}

